/* R1085: the same formal invoice and statement table in both store portals. */
(()=>{'use strict';
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),n=v=>Number(v||0),fa=v=>n(v).toLocaleString('fa-IR'),money=v=>fa(v)+' تومان';
const dateFa=v=>{if(!v)return '—';const d=new Date(v);return Number.isFinite(d.getTime())?new Intl.DateTimeFormat('fa-IR-u-ca-persian',{timeZone:'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit'}).format(d):'—'};
const range=x=>x.rental_start?dateFa(x.rental_start)+(x.rental_end&&x.rental_end!==x.rental_start?' تا '+dateFa(x.rental_end):''):'—';
const gearName=r=>r.title||[r.category,r.brand,r.model].filter(Boolean).join(' ')||'تجهیز';
const items=x=>Array.isArray(x.items)?x.items:[];
 function invoicePaper(x,options={}){const shop=options.shop||{};const shopHeader=(title,meta)=>`<header class="pb922Head"><div><h1>${h(shop.name||'فروشگاه تجهیزات')}</h1><p class="pb922Muted">${h([shop.phone,shop.address].filter(Boolean).join(' · '))}</p></div><div><h2>${h(title)}</h2><p>${meta}</p><p class="pb922Muted">مبالغ به تومان</p></div></header>`;const rows=items(x),gross=rows.length?rows.reduce((sum,r)=>sum+n(r.subtotal),0):n(x.gross_amount??x.total_amount),discount=n(x.discount_amount),total=n(x.total_amount);return `<article class="pb922Paper" data-pb922-invoice>${shopHeader(x.kind==='sale'?'فاکتور فروش تجهیزات':'فاکتور اجاره تجهیزات','شماره: <b dir="ltr">'+h(x.invoice_number||'—')+'</b> · '+dateFa(x.issued_at))}<section class="pb922Facts"><div><b>عکاس / مشتری:</b> ${h(x.photographer_name||'—')}</div><div><b>شماره تماس:</b> <span dir="ltr">${h(x.photographer_mobile||'—')}</span></div><div><b>تاریخ آفیش:</b> ${h(range(x))}</div><div><b>مهلت برگشت:</b> ${h(options.returnDeadline||'—')}</div></section><div class="pb922TableScroll"><table><thead><tr><th>ردیف</th><th>شرح تجهیزات</th><th>تعداد</th><th>روز</th><th>${x.kind==='sale'?'قیمت واحد':'اجاره روزانه'}</th><th>مبلغ</th></tr></thead><tbody>${rows.length?rows.map((r,i)=>`<tr><td>${fa(i+1)}</td><td>${h((options.equipmentName||gearName)(r))}</td><td>${fa(n(r.quantity))}</td><td>${fa(n(r.rental_days||x.rental_days||1))}</td><td>${money(r.daily_price??r.unit_price)}</td><td>${money(r.subtotal)}</td></tr>`).join(''):`<tr><td>۱</td><td colspan="4">${h(x.item_titles||'آفیش تجهیزات')}<br><small>جزئیات اقلام در این فاکتور ثبت نشده است.</small></td><td>${money(total)}</td></tr>`}</tbody></table></div><section class="pb922Totals"><div><span>جمع اقلام</span><b>${money(gross)}</b></div><div><span>تخفیف</span><b>${money(discount)}</b></div>${gross-discount!==total?`<div><span>${h(x.return_kind==='late'&&total-(gross-discount)>0?'جریمه / دیرکرد':'اصلاح مبلغ فاکتور')}</span><b>${money(total-(gross-discount))}</b></div>`:''}<div class="pb922Grand"><span>مبلغ نهایی فاکتور</span><b>${money(total)}</b></div><div><span>ودیعه (جدا از اجاره)</span><b>${money(x.deposit_amount)}</b></div></section>${x.invoice_adjustment_note?`<p class="pb923InvoiceNote"><b>توضیح اصلاح فاکتور:</b> ${h(x.invoice_adjustment_note)}</p>`:''}<section class="pb922Sign"><span>مهر و امضای فروشگاه</span><span>امضای مشتری / عکاس</span></section><footer class="pb922Footer">وضعیت پرداخت: ${x.payment_status==='paid'?'پرداخت‌شده':'ثبت‌شده'} · صادرشده از PhotoBridge</footer></article>`}
function ledgerTable(rows,opening=0){let running=n(opening);return `<div class="pb922TableScroll"><table class="accountingTable"><thead><tr><th>ردیف</th><th>تاریخ</th><th>شرح</th><th>بدهکار</th><th>بستانکار</th><th>مانده</th></tr></thead><tbody>${rows.length?rows.map((r,i)=>{running+=r.direction==='debit'?n(r.amount):-n(r.amount);return `<tr><td>${fa(i+1)}</td><td>${h(r.rental_start?range(r):dateFa(r.entry_date||r.created_at))}</td><td>${h(r.description||'گردش حساب')}</td><td>${r.direction==='debit'?money(r.amount):'—'}</td><td>${r.direction==='credit'?money(r.amount):'—'}</td><td>${running===0?'تسویه':money(Math.abs(running))+(running>0?' بدهکار':' بستانکار')}</td></tr>`}).join(''):'<tr><td colspan="6">در این بازه گردش حسابی ثبت نشده است.</td></tr>'}</tbody></table></div>`;}
window.pbR1085Finance={invoicePaper,ledgerTable};
})();
